<?php require_once 'bootstrap.php';$u=require_login();$pageTitle='Cortex';require '_header.php';?><section class="cortex-head"><div class="cortex-orb">✦</div><h1>Ciao <?=h($u['display_name'])?>.</h1><p>Scrivi o parla. La conversazione personale è privata; gli insight condivisi sono solo aggregati/de-identificati.</p></section><div class="prompt-grid"><button data-fill="Vorrei parlare di come sto oggi">💬 Voglio parlare</button><button data-fill="Trova il Club più vicino a me">🤝 Trova Club</button><button data-fill="Quali eventi sono in programma?">📅 Eventi</button><button data-fill="Spiegami il metodo Hudolin">🎓 Metodo</button></div><section class="chat-shell"><div id="chatMessages"><div class="msg ai">Sono Cortex. Posso usare la conoscenza Neuralog e il registro DEPENDEX; se una risposta non è ancorata, te lo dico.</div></div><form id="chatForm"><button type="button" id="voiceBtn" aria-label="Parla">🎙</button><input id="chatInput" maxlength="1000" placeholder="Scrivi qui…" autocomplete="off"><button aria-label="Invia">➤</button></form></section><script>
let dxConv='';const form=document.querySelector('#chatForm'),inp=document.querySelector('#chatInput'),box=document.querySelector('#chatMessages');function add(role,text){const d=document.createElement('div');d.className='msg '+role;d.textContent=text;box.appendChild(d);box.scrollTop=box.scrollHeight;return d}form.addEventListener('submit',async e=>{e.preventDefault();let q=inp.value.trim();if(!q)return;add('user',q);inp.value='';let wait=add('ai','Sto cercando nella conoscenza…');try{let r=await fetch('cortex-api.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({q,conversation_sic_id:dxConv})});let j=await r.json();wait.remove();if(j.ok){dxConv=j.conversation_sic_id;add('ai',j.answer);if('speechSynthesis' in window&&document.body.dataset.voice==='on'){speechSynthesis.speak(new SpeechSynthesisUtterance(j.answer))}}else add('ai','Non riesco a rispondere ora.')}catch(err){wait.textContent='Connessione non disponibile.'}});document.querySelectorAll('[data-fill]').forEach(b=>b.onclick=()=>{inp.value=b.dataset.fill;inp.focus()});const vb=document.querySelector('#voiceBtn');const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){const rec=new SR();rec.lang='it-IT';rec.interimResults=false;vb.onclick=()=>rec.start();rec.onresult=e=>{inp.value=e.results[0][0].transcript;inp.focus()};}else vb.disabled=true;</script><?php require '_footer.php';?>